const LETTER_PITCH = { C:0, D:2, E:4, F:5, G:7, A:9, B:11 }
const LETTERS = ["C","D","E","F","G","A","B"]
const DEGREE_SEMITONES = { "1":0,"b2":1,"2":2,"#2":3,"b3":3,"3":4,"4":5,"#4":6,"b5":6,"5":7,"#5":8,"b6":8,"6":9,"#6":10,"b7":10,"7":11,"9":2,"11":5,"13":9 }
const DEGREE_LETTER = { "1":0,"b2":1,"2":1,"#2":1,"b3":2,"3":2,"4":3,"#4":3,"b5":4,"5":4,"#5":4,"b6":5,"6":5,"#6":5,"b7":6,"7":6,"9":1,"11":3,"13":5 }
const ROMAN_DEG = { I:"1", II:"2", III:"3", IV:"4", V:"5", VI:"6", VII:"7" }

function parseRoot(key){ let p=LETTER_PITCH[key[0]]; for(const c of key.slice(1)){ if(c==="#")p++; if(c==="b")p-- } return { letter:key[0], pitch:(p+120)%12 } }
function accidental(n){ return n>0?"#".repeat(n):n<0?"b".repeat(-n):"" }
function spellDegree(deg,key){ const base=deg.replace(/^([b#])/,""); let norm=deg; if(base==="8")norm="1"; if(!(norm in DEGREE_SEMITONES))return deg; const root=parseRoot(key), target=(root.pitch+DEGREE_SEMITONES[norm])%12; const letter=LETTERS[(LETTERS.indexOf(root.letter)+DEGREE_LETTER[norm])%7]; let diff=target-LETTER_PITCH[letter]; while(diff>6)diff-=12; while(diff<-6)diff+=12; return letter+accidental(diff) }
function parseRoman(input){ let raw=(input||"").trim().replace(/♭/g,"b").replace(/♯/g,"#").replace(/Δ/g,"maj").replace(/−/g,"-"); if(!raw||/^(N\.?C\.?)$/i.test(raw))return{nc:true,raw:"N.C."}; let bass=null; let slash=raw.lastIndexOf("/"); if(slash>0){ const aft=raw.slice(slash+1),before=raw.slice(0,slash); const isSixNine=aft==="9"&&/6$/.test(before); if(!isSixNine&&/^[b#]?(?:[1-7]|9|11|13)$/.test(aft)){ bass=aft; raw=before } } let m=raw.match(/^([b#]?)([ivIV]+)(.*)$/); if(!m)return{error:true,raw:input}; const accidentalPrefix=m[1],roman=m[2],suffix=m[3]||""; const upper=roman.toUpperCase(); const number=ROMAN_DEG[upper]; if(!number)return{error:true,raw:input}; const degree=accidentalPrefix+number; const minor=roman===roman.toLowerCase(); let quality=suffix; if(quality==="°7"||quality==="dim7")quality="dim7"; else if(quality==="ø7")quality="m7b5"; else if(minor){ if(!quality)quality="m"; else if(quality==="7")quality="m7"; else if(quality==="9")quality="m9"; else if(quality==="6")quality="m6"; else if(quality==="6/9")quality="m6/9"; else if(quality==="add9")quality="madd9"; else if(quality==="(maj7)")quality="m(maj7)"; else if(!quality.startsWith("m"))quality="m"+quality } return { degree, quality, bass, raw:input, nc:false } }

// ── Desert-Noir quality → DukeBox canonical quality ──────────────────────────
const Q_MAP = {
  "":"maj", "m":"min", "maj7":"maj7", "maj9":"maj9", "maj7#11":"maj7#11",
  "add9":"add9", "6":"maj6", "m6":"min6", "m6/9":"min6/9", "m7":"min7",
  "m9":"min9", "madd9":"minadd9", "m(maj7)":"min(maj7)", "m7b5":"min7b5",
  "dim7":"dim7", "7":"7", "9":"9", "7sus":"7sus4", "sus":"sus4",
  "7b9":"7b9", "7alt":"7alt", "alt":"7alt",
}

function tokenToBar(token, key, section, beats){
  const p = parseRoman(token)
  if(p.nc || p.error) return { root:null, quality:"NC", symbol:"N.C.", section, beats }
  const root = spellDegree(p.degree, key)
  const bass = p.bass ? spellDegree(p.bass, key) : null
  const quality = Q_MAP[p.quality] ?? "maj7"
  let symbol = buildChordSymbol(root, quality)
  if(bass) symbol += "/" + bass
  const bar = { root, quality, symbol, section, beats }
  if(bass) bar.bass = bass
  return bar
}

// Several sketches carry a mid-song meter shift in their own m.meter text
// (e.g. "4/4 → 6/8", "4/4 + 2/4") that a single song-level field can't
// represent — those are left as plain descriptive text (still shown by
// DesertNoirPanel) and the song defaults to 4/4 here, unchanged from before
// this field existed. Only an exact match against JAZZ_METERS becomes a
// real, playable `form.meter`.
function toForm(m){
  const key = "C"
  const keyMode = m.family === "minor" ? "minor" : "major"
  const meter = JAZZ_METERS.includes(m.meter) ? m.meter : undefined
  const beatsPerBar = METER_BEATS[meter] ?? 4
  const bars = []
  const sections = []
  m.sections.forEach(sec => {
    let count = 0
    sec.bars.forEach(tokens => {
      const n = tokens.length
      const beats = n === 1 ? beatsPerBar : Math.max(1, Math.floor(beatsPerBar / n))
      tokens.forEach(tok => { bars.push(tokenToBar(tok, key, sec.name, beats)); count++ })
    })
    sections.push({ name: sec.name, repeat: sec.repeat || 1, note: sec.note || "", bars: count })
  })
  return {
    keyRoot: key, keyMode, tempo: m.tempo, meter, bars, sections,
    meta: {
      title: m.title, number: m.number, collection: m.collection, vibe: m.vibe,
      family: m.family, modeLabel: m.modeLabel, meter: m.meter, groove: m.groove,
      description: m.description, bridgeTechnique: m.bridgeTechnique,
      melodyNote: m.melodyNote, tone: m.tone, arrangement: m.arrangement,
      bassLine: m.bass, melodyLine: m.melody,
    },
  }
}

export const DESERT_NOIR_FORMS = {}
export const DESERT_NOIR_META = {}
for (const m of DN_MODELS) {
  const name = `${m.title} — Desert Noir`
  const form = toForm(m)
  DESERT_NOIR_FORMS[name] = form
  DESERT_NOIR_META[name] = form.meta
}
export const DESERT_NOIR_NAMES = Object.keys(DESERT_NOIR_FORMS)
